<x-layouts::app :title="__('Daily update')"><div class="mx-auto max-w-2xl p-4 md:p-8"><h1 class="mb-5 text-2xl font-semibold">{{ $workUpdate->exists ? 'Edit daily update' : 'Submit daily update' }}</h1><form method="POST" action="{{ $workUpdate->exists ? route('updates.update',$workUpdate) : route('updates.store') }}" class="grid gap-4 rounded-xl border p-5">@csrf @if($workUpdate->exists)@method('PUT')@endif @foreach($errors->all() as $error)<p class="text-red-600">{{ $error }}</p>@endforeach<label>Work date<input type="date" required name="work_date" value="{{ old('work_date',$workUpdate->work_date?->format('Y-m-d') ?? today()->format('Y-m-d')) }}" class="mt-1 w-full rounded-lg border bg-transparent p-2"></label><label>Related task (optional)<select name="task_id" class="mt-1 w-full rounded-lg border bg-transparent p-2"><option value="">None</option>@foreach($tasks as $task)<option value="{{ $task->id }}" @selected(old('task_id',$workUpdate->task_id)==$task->id)>{{ $task->title }}</option>@endforeach</select></label><label>Completed work<textarea required name="completed_work" class="mt-1 w-full rounded-lg border bg-transparent p-2">{{ old('completed_work',$workUpdate->completed_work) }}</textarea></label><label>Pending work<textarea name="pending_work" class="mt-1 w-full rounded-lg border bg-transparent p-2">{{ old('pending_work',$workUpdate->pending_work) }}</textarea></label><label>Blockers or issues<textarea name="blockers" class="mt-1 w-full rounded-lg border bg-transparent p-2">{{ old('blockers',$workUpdate->blockers) }}</textarea></label><button class="rounded-lg bg-blue-600 px-4 py-2 text-white">Save update</button></form></div></x-layouts::app>
